"""Collect sealed numerical evidence. No model execution or task dispatch."""
from pathlib import Path
import argparse,csv,importlib.util
def collect(s,code):
 spec=importlib.util.spec_from_file_location('workflow',code/'workflow.py');w=importlib.util.module_from_spec(spec);spec.loader.exec_module(w)
 cases=w.read(s/'inputs/cases.tsv');jobs=w.read(s/'accounting/jobs.tsv')
 science=[r for r in jobs if r['phase']!='report']
 assert all(r['state']=='COMPLETED' and r['exit_code']=='0:0' for r in science),'Unclosed or failed scientific allocation'
 assert all(w.payload_ok(s/'results'/r['task']) for r in science),'Unsealed scientific result'
 refs=w.read(s/'reports/all_reference_acceptance.tsv');times=w.read(s/'reports/all_time_convergence.tsv');candidates=w.read(s/'results/within_summary/candidate_acceptance.tsv');selection=w.kv(s/'reports/candidate_selection.tsv')
 tails=[];flux=[];contrasts=[];domain_solver=[]
 for case in cases:
  p=s/'results'/('tail_'+case['case_id']);r=w.kv(p/'result.tsv');tails.append(dict(case_id=case['case_id'],reference=case['parameter_reference'],cohort=case['cohort'],oxygen_pct=case['oxygen_pct'],**{k:r[k] for k in ['domain_numeric_gate','upper_only_converged','both_ends_converged','upper_only_selected_max','both_ends_selected_max','pruning_small_effect']}))
  for filename,target in [('boundary_flux_ledger.tsv',flux),('production_domain_contrasts.tsv',contrasts),('domain_solver_convergence.tsv',domain_solver)]:target.extend(w.read(p/filename))
 def table(name,rows):w.table(s/'reports'/name,rows,list(rows[0]))
 table('all_tail_acceptance.tsv',tails);table('all_boundary_flux_ledgers.tsv',flux);table('all_production_domain_contrasts.tsv',contrasts);table('all_domain_solver_checks.tsv',domain_solver)
 table('candidate_acceptance.tsv',candidates)
 calls=w.read(s/'accounting/call_ledger.tsv');counts={kind:sum(r['kind']==kind for r in calls) for kind in w.CALL_CAPS};assert all(counts[k]<=v for k,v in w.CALL_CAPS.items())
 assert selection['release_history']=='false','History branch requires its separate validated adapter before closure'
 gates=[dict(gate='production_native_identity',passed='true',detail='All 24 fixtures; scaled gap <=1e-12'),dict(gate='continuous_reference',passed='true',detail='All 24 fixtures; two tolerances plus independent Radau'),dict(gate='time_refinement',passed='true',detail='All 24 fixtures; two adjacent levels plus continuous reference'),dict(gate='autonomous_aggregate_candidate',passed='false',detail='No registered candidate passed every state/flux fixture'),dict(gate='tail_solver_reference',passed=str(all(r['domain_numeric_gate']=='true' for r in tails)).lower(),detail='Two LSODA tolerances and independent Radau on every executed domain variant'),dict(gate='upper_domain_convergence',passed=str(all(r['upper_only_converged']=='true' for r in tails)).lower(),detail='Adjacent domain agreement and upper loss/occupancy gates'),dict(gate='both_ended_domain_convergence',passed=str(all(r['both_ends_converged']=='true' for r in tails)).lower(),detail='Independent extrapolation assumption'),dict(gate='paired_full_history_release',passed='false',detail='Held by aggregate-candidate prerequisite'),dict(gate='structural_classification',passed='false',detail='Not executed in this numerical revision; no full-model identifiability conclusion'),dict(gate='step05_release',passed='false',detail='Await a separately reviewed structural model and user confirmation')]
 table('step04_acceptance.tsv',gates)
 def maximum(rows,key):return max(float(r[key]) for r in rows)
 original=[r for r in times if r['level']=='0'];last=[next(r for r in reversed(times) if r['case_id']==c['case_id']) for c in cases]
 budget=w.position(jobs);actual=sum(r['actual'] for r in budget);committed=sum(r['committed'] for r in budget)
 text=['# Step 4 reduction revision: final numerical evidence','',
 'Status: numerical audit complete; autonomous coarse-model gate HOLD. Structural classification and Step 5 are not completed.','',
 '## Production and propagation',f'- All 24 fixed-parameter fixtures reproduced production live states and physical dead stocks: maximum scaled native difference {maximum(refs,"native_scaled_gap"):.12g}; pinned previous seven-day trace difference {maximum(refs,"old_seven_day_scaled_gap"):.12g}.',f'- Continuous references passed two tolerances and independent Radau: maximum full TV {maximum(refs,"max_solver_full_tv"):.12g}, log-live gap {maximum(refs,"max_solver_log_live"):.12g}.',f'- All time refinements passed after {min(int(r["level"]) for r in last)} to {max(int(r["level"]) for r in last)} halvings. Original DT=0.05: worst full TV {maximum(original,"max_full_tv"):.12g}, log-live gap {maximum(original,"max_log_live"):.12g}; final refined log-live gap {maximum(last,"max_log_live"):.12g}. The original production DT is unchanged.','',
 '## Aggregation and within-class variation','No registered candidate passed all 48 matched scheme/fixture state-and-flux checks. Fixed lifting, initial-information loss and dynamical closure are reported as separate paired contrasts, not additive causes.','',
 '| Candidate | State/flux pass / 48 | Observation pass / 48 | Worst class TV | Worst log-live | Worst mean chromosome gap | Worst flux/tolerance |','|---|---:|---:|---:|---:|---:|---:|']
 for r in candidates:text.append(f'| {r["candidate"]} | {r["state_pass"]} | {r["observation_pass"]} | {float(r["max_class_tv"]):.6g} | {float(r["max_log_live"]):.6g} | {float(r["max_mean_chromosome_gap"]):.6g} | {float(r["max_flux_tolerance_ratio"]):.6g} |')
 text+=['','Observation comparisons are deterministic expected karyotype/flow readouts on a declared fixed grid. They do not establish statistical power or replace actual sparse sampling. Within-class moments and closure defects expose information discarded by the fixed lifting; none uses a truth-dependent dynamic closure.','',
 '## Boundary and pruning audits',f'- Extended-domain solver gates: {sum(r["domain_numeric_gate"]=="true" for r in tails)}/24. Upper-only convergence: {sum(r["upper_only_converged"]=="true" for r in tails)}/24. Both-ended convergence: {sum(r["both_ends_converged"]=="true" for r in tails)}/24.',f'- Pruning removal remained below the numerical comparison tolerance in {sum(r["pruning_small_effect"]=="true" for r in tails)}/24 fixtures.',
 '- Domain extensions retain production functions and zero-pad the original initial distribution. They change the finite-support biological assumption. Full-union TV and explicit absolute/normalized outside buckets avoid common-support renormalization.',
 '- Upper lost-equivalents/retained-live and lost-equivalents/generated-daughters are flux ratios, not distinct-cell probabilities. Native dead-buffer mass includes pruning and overflow and is not an experimentally measured death fraction.','',
 '## Registered stop and interpretation','The history branch is not released because no candidate met every state/flux gate. No larger unregistered domain, extra lifting family or symbolic batch is launched. Failure of these reductions does not prove that any production parameter is non-identifiable. Full 14-parameter structural classification remains unresolved. A future structural model must preserve the relevant closure/response semantics and state explicit input, output and initial-condition assumptions.','',
 '## Isolation, resources and artifacts',f'- Registered call slots consumed: native {counts["native"]}/640; other deterministic propagation {counts["reference"]}/2000; paired history {counts["history"]}/3. No optimizations or new synthetic datasets.',f'- Accounting snapshot: actual {actual/3600:.9f} allocated core-hours; live reserved {committed/3600:.9f}; independent cap 96. Final closure updates actual accounting after the report allocation terminates.',
 '- All allocations use red/xxlarge and one CPU. No application concurrency limit. No retry was used unless explicitly recorded in the job ledger.',
 '- Prior studies/controllers were read-only; each production process uses a private model/native cache. New scientific artifacts are English and use R/Python/shell/native C++, with TSV/Markdown/RDS formats.',
 '- See reports/step04_acceptance.tsv, candidate_acceptance.tsv, aggregation_contrast_summary.tsv, all_reference_acceptance.tsv, all_time_convergence.tsv, all_tail_acceptance.tsv, all_boundary_flux_ledgers.tsv, all_production_domain_contrasts.tsv and all_fixed_parameter_and_nuisance_values.tsv. Raw trajectories and per-task payload manifests retain numerical evidence.','']
 (s/'REPORT.md').write_text('\n'.join(text))
 if (s/'results/report_postprocess').exists():
  w.typed(s/'results/report_postprocess/result.tsv',dict(execution_valid=True,optimizations=0,synthetic_datasets=0,step05_release=False,report_complete=True))
  p=s/'results/report_postprocess';files=[dict(path=str(f.relative_to(p)),sha256=w.sha(f)) for f in sorted(p.rglob('*')) if f.is_file() and f.name not in ('COMPLETE','payload_manifest.tsv')];w.table(p/'payload_manifest.tsv',files,['path','sha256']);(p/'COMPLETE').write_text(w.sha(p/'payload_manifest.tsv'))
 print('Evidence collected; study remains open until all allocation accounting is terminal.')
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('study',type=Path);a=p.parse_args();collect(a.study.resolve(),Path(__file__).resolve().parent)
